1	import { TitleSkeleton, useDesignSystemTheme } from '@databricks/design-system';
2	import { ExperimentPageTabName } from '../../../constants';
3	import { ExperimentKind } from '../../../constants';
4	import { useExperimentEvaluationRunsData } from '../../../components/experiment-page/hooks/useExperimentEvaluationRunsData';
5	import type { ExperimentPageSideNavSectionKey } from './constants';
6	import { COLLAPSED_CLASS_NAME, FULL_WIDTH_CLASS_NAME, useExperimentPageSideNavConfig } from './constants';
7	import { ExperimentPageSideNavSection } from './ExperimentPageSideNavSection';
8	import { ExperimentPageSideNavAssistantButton } from './ExperimentPageSideNavAssistantButton';
9	import { useParams } from '@mlflow/mlflow/src/common/utils/RoutingUtils';
10	
11	const SIDE_NAV_WIDTH = 160;
12	const SIDE_NAV_COLLAPSED_WIDTH = 32;
13	
14	export const ExperimentPageSideNav = ({
15	  experimentKind,
16	  activeTab,
17	}: {
18	  experimentKind: ExperimentKind;
19	  activeTab: ExperimentPageTabName;
20	}) => {
21	  const { theme } = useDesignSystemTheme();
22	  const { experimentId } = useParams();
23	  // the single chat session tab also has a sidebar. to conserve
24	  // horizontal space, we force the side nav to be collapsed in this tab
25	  const forceCollapsed = activeTab === ExperimentPageTabName.SingleChatSession;
26	
27	  const isGenAIExperiment =
28	    experimentKind === ExperimentKind.GENAI_DEVELOPMENT || experimentKind === ExperimentKind.GENAI_DEVELOPMENT_INFERRED;
29	
30	  const { trainingRuns } = useExperimentEvaluationRunsData({
31	    experimentId: experimentId || '',
32	    enabled: isGenAIExperiment,
33	    filter: '', // not important in this case, we show the runs tab if there are any training runs
34	  });
35	
36	  const hasTrainingRuns = trainingRuns?.length > 0;
37	
38	  const sideNavConfig = useExperimentPageSideNavConfig({
39	    experimentKind,
40	    hasTrainingRuns,
41	  });
42	
43	  return (
44	    <div
45	      css={{
46	        display: 'flex',
47	        flexDirection: 'column',
48	        paddingTop: theme.spacing.sm,
49	        paddingRight: theme.spacing.sm,
50	        borderRight: `1px solid ${theme.colors.border}`,
51	        boxSizing: 'content-box',
52	        width: SIDE_NAV_COLLAPSED_WIDTH,
53	        [`& .${COLLAPSED_CLASS_NAME}`]: {
54	          display: 'flex',
55	        },
56	        [`& .${FULL_WIDTH_CLASS_NAME}`]: {
57	          display: 'none',
58	        },
59	        ...(!forceCollapsed
60	          ? {
61	              [theme.responsive.mediaQueries.xl]: {
62	                width: SIDE_NAV_WIDTH,
63	                [`& .${COLLAPSED_CLASS_NAME}`]: {
64	                  display: 'none',
65	                },
66	                [`& .${FULL_WIDTH_CLASS_NAME}`]: {
67	                  display: 'flex',
68	                },
69	              },
70	            }
71	          : {}),
72	      }}
73	    >
74	      <div css={{ display: 'flex', flexDirection: 'column', justifyContent: 'space-between', height: '100%' }}>
75	        <div>
76	          {Object.entries(sideNavConfig).map(([sectionKey, items]) => (
77	            <ExperimentPageSideNavSection
78	              key={sectionKey}
79	              activeTab={activeTab}
80	              sectionKey={sectionKey as ExperimentPageSideNavSectionKey}
81	              items={items}
82	            />
83	          ))}
84	        </div>
85	        <ExperimentPageSideNavAssistantButton />
86	      </div>
87	    </div>
88	  );
89	};
90	
91	export const ExperimentPageSideNavSkeleton = () => {
92	  const { theme } = useDesignSystemTheme();
93	  return (
94	    <div
95	      css={{
96	        display: 'flex',
97	        flexDirection: 'column',
98	        paddingTop: theme.spacing.sm,
99	        paddingRight: theme.spacing.sm,
100	        borderRight: `1px solid ${theme.colors.border}`,
101	        width: SIDE_NAV_COLLAPSED_WIDTH,
102	        [theme.responsive.mediaQueries.xl]: {
103	          width: SIDE_NAV_WIDTH,
104	        },
105	      }}
106	    >
107	      <TitleSkeleton css={{ width: '60%' }} />
108	      <TitleSkeleton css={{ width: '80%' }} />
109	      <TitleSkeleton css={{ width: '70%' }} />
110	    </div>
111	  );
112	};
