import {
  START_TIME_LABEL_QUERY_PARAM_KEY,
  START_TIME_QUERY_PARAM_KEY,
  END_TIME_QUERY_PARAM_KEY,
} from '../../../hooks/useMonitoringFilters';

export const isTracesRelatedTab = (tabName: ExperimentPageTabName) => {
  return (
    tabName === ExperimentPageTabName.Overview ||
    tabName === ExperimentPageTabName.Traces ||
    tabName === ExperimentPageTabName.SingleChatSession ||
    tabName === ExperimentPageTabName.ChatSessions
  );
};

// Time range filter params are shared across all tabs and must be preserved when
// navigating between any two tabs. Every other query param is considered
// tab-specific and is only preserved when navigating within the same tab group.
const TIME_RANGE_QUERY_PARAM_KEYS = [
  START_TIME_LABEL_QUERY_PARAM_KEY,
  START_TIME_QUERY_PARAM_KEY,
  END_TIME_QUERY_PARAM_KEY,
];

/**
 * Computes the query string to attach to a side-nav link based on the current and target tabs.
 *
 * - Navigating between two traces-related tabs preserves ALL current query params (both time
 *   range params and traces-specific params such as selectedTraceId).
 * - Navigating into, out of, or entirely outside the traces tab group preserves ONLY the time
 *   range params (e.g. startTimeLabel, startTime); all other tab-specific params are dropped.
 *
 * Returns `undefined` when there is nothing to preserve so the link carries no query string.
 */
export const getSideNavLinkSearch = (
  search: string,
  activeTab: ExperimentPageTabName,
  targetTab: ExperimentPageTabName,
): string | undefined => {
  if (isTracesRelatedTab(activeTab) && isTracesRelatedTab(targetTab)) {
    return search || undefined;
  }

  const currentParams = new URLSearchParams(search);
  const preservedParams = new URLSearchParams();
  for (const key of TIME_RANGE_QUERY_PARAM_KEYS) {
    const value = currentParams.get(key);
    if (value !== null) {
      preservedParams.set(key, value);
    }
  }

  const preservedSearch = preservedParams.toString();
  return preservedSearch ? `?${preservedSearch}` : undefined;
};
