26	/**
27	 * Computes the query string to attach to a side-nav link based on the current and target tabs.
28	 *
29	 * - Navigating between two traces-related tabs preserves ALL current query params (both time
30	 *   range params and traces-specific params such as selectedTraceId).
31	 * - Navigating into, out of, or entirely outside the traces tab group preserves ONLY the time
32	 *   range params (e.g. startTimeLabel, startTime); all other tab-specific params are dropped.
33	 *
34	 * Returns `undefined` when there is nothing to preserve so the link carries no query string.
35	 */
36	export const getSideNavLinkSearch = (
37	  search: string,
38	  activeTab: ExperimentPageTabName | undefined,
39	  targetTab: ExperimentPageTabName,
40	): string | undefined => {
41	  if (activeTab && isTracesRelatedTab(activeTab) && isTracesRelatedTab(targetTab)) {
42	    return search || undefined;
43	  }
44	
45	  const currentParams = new URLSearchParams(search);
46	  const preservedParams = new URLSearchParams();
47	  for (const key of TIME_RANGE_QUERY_PARAM_KEYS) {
48	    const value = currentParams.get(key);
49	    if (value !== null) {
50	      preservedParams.set(key, value);
51	    }
52	  }
53	
54	  const preservedSearch = preservedParams.toString();
55	  return preservedSearch ? `?${preservedSearch}` : undefined;
